import React, { useState } from 'react';
import { 
  TextField, Button, Box, Typography, Alert, Snackbar 
} from '@mui/material';

const AddMeetingForm = ({ teamId, onAdd }) => {
  const [formData, setFormData] = useState({
    startTime: '',
    endTime: '',
    description: '',
    room: ''
  });
  const [error, setError] = useState('');
  const [openSnackbar, setOpenSnackbar] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.startTime || !formData.endTime || !formData.description || !formData.room) {
      setError('All fields are required');
      return;
    }

    if (new Date(formData.endTime) <= new Date(formData.startTime)) {
        setError('End time must be after start time');
        return;
    }

    try {
      await onAdd({ ...formData, teamId });
      setFormData({ startTime: '', endTime: '', description: '', room: '' });
      setError('');
      setOpenSnackbar(true);
    } catch (err) {
      setError(typeof err === 'string' ? err : 'Failed to add meeting');
    }
  };

  return (
    <Box component="form" onSubmit={handleSubmit} sx={{ mt: 4, p: 3, border: '1px solid #ddd', borderRadius: 2 }}>
      <Typography variant="h6" gutterBottom>Add New Meeting</Typography>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

      <TextField
        fullWidth
        margin="normal"
        label="Start Time"
        type="datetime-local"
        name="startTime"
        InputLabelProps={{ shrink: true }}
        value={formData.startTime}
        onChange={handleChange}
      />
      <TextField
        fullWidth
        margin="normal"
        label="End Time"
        type="datetime-local"
        name="endTime"
        InputLabelProps={{ shrink: true }}
        value={formData.endTime}
        onChange={handleChange}
      />
      <TextField
        fullWidth
        margin="normal"
        label="Description"
        name="description"
        value={formData.description}
        onChange={handleChange}
      />
      <TextField
        fullWidth
        margin="normal"
        label="Room"
        name="room"
        value={formData.room}
        onChange={handleChange}
      />

      <Button type="submit" variant="contained" color="primary" sx={{ mt: 2 }}>
        Schedule Meeting
      </Button>

      <Snackbar
        open={openSnackbar}
        autoHideDuration={6000}
        onClose={() => setOpenSnackbar(false)}
        message="Meeting added successfully"
      />
    </Box>
  );
};

export default AddMeetingForm;
